// Function node: Rate Limiter (Redis)
const redis = require('ioredis');
const client = new redis($credentials.redisUrl);

const key = 'ratelimit:brasilapi';
const limit = 30; // req/min
const windowMs = 60000;

const current = await client.incr(key);
if (current === 1) await client.pexpire(key, windowMs);

if (current > limit) {
  const ttl = await client.pttl(key);
  await new Promise(r => setTimeout(r, ttl));
  return { json: { ...$json, _rateLimited: true, waitMs: ttl } };
}

return { json: { ...$json, _rateLimited: false } };

code_snippets.retry_with_backoff:
// Code node: Retry Wrapper
const maxAttempts = 3;
const baseDelay = 2000;
let lastError;

for (let attempt = 1; attempt <= maxAttempts; attempt++) {
  try {
    const resp = await fetch($json.url, { timeout: 10000 });
    if (resp.ok || ![429,500,502,503,504].includes(resp.status)) {
      return { json: await resp.json() };
    }
    lastError = `HTTP ${resp.status}`;
  } catch (err) {
    lastError = err.message;
  }

  if (attempt < maxAttempts) {
    const delay = baseDelay * Math.pow(2, attempt - 1);
    await new Promise(r => setTimeout(r, delay));
  }
}

throw new Error(`Falhou após ${maxAttempts} tentativas: ${lastError}`);

