// Function node: Circuit Breaker (Redis)
const client = new redis($credentials.redisUrl);
const key = 'circuit:brasilapi';
const failures = await client.get(key);

if (failures && parseInt(failures) >= 5) {
  const ttl = await client.ttl(key);
  if (ttl > 0) {
    throw new Error(`Circuit breaker OPEN. Tenta novamente em ${ttl}s`);
  }
}

