// Scheduler: Prioriza clientes VIP
const { data: clientes } = await supabase
  .from('compliance_clientes')
  .select('id, cnpj, prioridade')
  .eq('ativo', true)
  .order('prioridade', { ascending: false }) // VIP primeiro
  .order('ultima_checagem', { ascending: true }); // Mais antigos primeiro

// Publica na queue com priority
for (const c of clientes) {
  await queue.add('check-cnpj', c, { priority: c.prioridade || 0 });
}
